/* OpenLearnHub — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0a0a23;
  --gold: #feac32;
  --blue-link: #002ead;
  --text: #1f2937;
  --muted: #6b7280;
  --border: #e5e7eb;
  --bg: #f9fafb;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--blue-link); }
img { max-width: 100%; }

/* CONTAINER */
.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }

/* HEADER */
.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 20px;
  padding-top: 14px;
  padding-bottom: 14px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 34px;
  height: 34px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.search-wrap {
  flex: 1;
  position: relative;
  max-width: 500px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 1rem;
}
.search-input {
  width: 100%;
  padding: 9px 12px 9px 36px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.1);
  color: #fff;
  font-size: 0.88rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.search-input::placeholder { color: #9ca3af; }
.search-input:focus {
  background: rgba(255,255,255,0.18);
  border-color: var(--gold);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.nav-link {
  color: #e5e7eb;
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 6px;
  transition: background 0.16s, color 0.16s;
}
.nav-link:hover { background: rgba(255,255,255,0.1); color: #fff; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: 8px 18px;
}
.nav-donate:hover { background: #f59e0b; }

/* HAMBURGER */
.hamburger {
  display: none;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 4px 8px;
  margin-left: auto;
  flex-shrink: 0;
}
.mobile-nav {
  display: none;
  flex-direction: column;
  background: #0f0f2e;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-nav.open { display: flex; }
.mobile-nav-link {
  color: #e5e7eb;
  padding: 14px 24px;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.15s;
}
.mobile-nav-link:hover { background: rgba(255,255,255,0.07); color: #fff; }

@media (max-width: 768px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .search-wrap { max-width: none; }
}

/* BANNER STRIP */
.banner-strip {
  background: var(--gold);
  color: var(--navy);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.88rem;
  font-weight: 600;
}
.banner-strip a { color: var(--navy); text-decoration: underline; }

/* SECTION TITLES */
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 24px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}

/* TAG LABELS */
.tag-label {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.tag-label a { color: inherit; }
.tag-ai { background: #eff6ff; color: #1d4ed8; }
.tag-scraping { background: #ecfdf5; color: #065f46; }
.tag-db { background: #f0fdf4; color: #166534; }
.tag-elastic { background: #faf5ff; color: #6b21a8; }
.tag-data { background: #fff7ed; color: #9a3412; }
.tag-python { background: #f0fdfa; color: #134e4a; }
.tag-js { background: #fefce8; color: #713f12; }
.tag-react { background: #e0f2fe; color: #0369a1; }
.tag-general { background: #f9fafb; color: #374151; }
.tag-automation { background: #fdf4ff; color: #86198f; }
.tag-node { background: #f0fdf4; color: #14532d; }
.tag-sheets { background: #f0fdf4; color: #15803d; }

/* PAGE MAIN */
.page-main { padding-top: 40px; flex: 1; }

/* FOOTER */
.site-footer {
  background: var(--navy);
  color: #9ca3af;
  margin-top: auto;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  padding: 48px 24px;
}
@media (max-width: 768px) {
  .footer-inner { grid-template-columns: 1fr; gap: 28px; }
}
.footer-mission p {
  font-size: 0.83rem;
  line-height: 1.7;
  margin-top: 14px;
  color: #9ca3af;
}
.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}
.footer-logo .logo-text { color: #fff; }
.footer-col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
