/* OpenLearnHub — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0a0a23;
  --gold: #feac32;
  --blue-link: #002ead;
  --text: #1f2937;
  --muted: #6b7280;
  --border: #e5e7eb;
  --bg: #f9fafb;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--blue-link); }
img { max-width: 100%; }

/* CONTAINER */
.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }

/* HEADER */
.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 20px;
  padding-top: 14px;
  padding-bottom: 14px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 34px;
  height: 34px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.search-wrap {
  flex: 1;
  position: relative;
  max-width: 500px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 1rem;
}
.search-input {
  width: 100%;
  padding: 9px 12px 9px 36px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.1);
  color: #fff;
  font-size: 0.88rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.search-input::placeholder { color: #9ca3af; }
.search-input:focus {
  background: rgba(255,255,255,0.18);
  border-color: var(--gold);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.nav-link {
  color: #e5e7eb;
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 6px;
  transition: background 0.16s, color 0.16s;
}
.nav-link:hover { background: rgba(255,255,255,0.1); color: #fff; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: 8px 18px;
}
.nav-donate:hover { background: #f59e0b; }

/* HAMBURGER */
.hamburger {
  display: none;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 4px 8px;
  margin-left: auto;
  flex-shrink: 0;
}
.mobile-nav {
  display: none;
  flex-direction: column;
  background: #0f0f2e;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-nav.open { display: flex; }
.mobile-nav-link {
  color: #e5e7eb;
  padding: 14px 24px;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.15s;
}
.mobile-nav-link:hover { background: rgba(255,255,255,0.07); color: #fff; }

@media (max-width: 768px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .search-wrap { max-width: none; }
}

