  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 34px;
  height: 34px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.search-wrap {
  flex: 1;
  position: relative;
  max-width: 500px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 1rem;
}
.search-input {
  width: 100%;
  padding: 9px 12px 9px 36px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.1);
  color: #fff;
  font-size: 0.88rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.search-input::placeholder { color: #9ca3af; }
.search-input:focus {
  background: rgba(255,255,255,0.18);
  border-color: var(--gold);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.nav-link {
  color: #e5e7eb;
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 6px;
  transition: background 0.16s, color 0.16s;
}
.nav-link:hover { background: rgba(255,255,255,0.1); color: #fff; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: 8px 18px;
}
.nav-donate:hover { background: #f59e0b; }

/* HAMBURGER */
.hamburger {
