  flex-direction: column;
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--blue-link); }
img { max-width: 100%; }

/* CONTAINER */
.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }

/* HEADER */
.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 20px;
  padding-top: 14px;
  padding-bottom: 14px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 34px;
  height: 34px;
  background: var(--gold);
  color: var(--navy);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
}
.search-wrap {
  flex: 1;
  position: relative;
  max-width: 500px;
}
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 1rem;
}
.search-input {
  width: 100%;
  padding: 9px 12px 9px 36px;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.1);
  color: #fff;
  font-size: 0.88rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.search-input::placeholder { color: #9ca3af; }
.search-input:focus {
  background: rgba(255,255,255,0.18);
  border-color: var(--gold);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.nav-link {
  color: #e5e7eb;
  font-size: 0.9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 6px;
  transition: background 0.16s, color 0.16s;
}
.nav-link:hover { background: rgba(255,255,255,0.1); color: #fff; }
.nav-donate {
  background: var(--gold);
  color: var(--navy) !important;
  font-weight: 700;
  padding: 8px 18px;
}
.nav-donate:hover { background: #f59e0b; }

/* HAMBURGER */
.hamburger {
  display: none;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 4px 8px;
  margin-left: auto;
  flex-shrink: 0;
}
.mobile-nav {
  display: none;
  flex-direction: column;
  background: #0f0f2e;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-nav.open { display: flex; }
.mobile-nav-link {
  color: #e5e7eb;
  padding: 14px 24px;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background 0.15s;
}
.mobile-nav-link:hover { background: rgba(255,255,255,0.07); color: #fff; }

@media (max-width: 768px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .search-wrap { max-width: none; }
}

/* BANNER STRIP */
.banner-strip {
  background: var(--gold);
  color: var(--navy);
  text-align: center;
  padding: 10px 24px;
  font-size: 0.88rem;
  font-weight: 600;
}
.banner-strip a { color: var(--navy); text-decoration: underline; }

/* SECTION TITLES */
.section-title {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 24px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}

/* TAG LABELS */
.tag-label {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.tag-label a { color: inherit; }
.tag-ai { background: #eff6ff; color: #1d4ed8; }
.tag-scraping { background: #ecfdf5; color: #065f46; }
.tag-db { background: #f0fdf4; color: #166534; }
.tag-elastic { background: #faf5ff; color: #6b21a8; }
.tag-data { background: #fff7ed; color: #9a3412; }
.tag-python { background: #f0fdfa; color: #134e4a; }
.tag-js { background: #fefce8; color: #713f12; }
.tag-react { background: #e0f2fe; color: #0369a1; }
.tag-general { background: #f9fafb; color: #374151; }
.tag-automation { background: #fdf4ff; color: #86198f; }
.tag-node { background: #f0fdf4; color: #14532d; }
.tag-sheets { background: #f0fdf4; color: #15803d; }

/* PAGE MAIN */
.page-main { padding-top: 40px; flex: 1; }

/* FOOTER */
.site-footer {
  background: var(--navy);
  color: #9ca3af;
  margin-top: auto;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  padding: 48px 24px;
}
@media (max-width: 768px) {
  .footer-inner { grid-template-columns: 1fr; gap: 28px; }
}
.footer-mission p {
  font-size: 0.83rem;
  line-height: 1.7;
  margin-top: 14px;
  color: #9ca3af;
}
.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}
.footer-logo .logo-text { color: #fff; }
.footer-col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.footer-tags, .footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.footer-tags a, .footer-links a {
  font-size: 0.8rem;
  color: #9ca3af;
  transition: color 0.15s;
  padding: 2px 0;
}
.footer-tags a::after { content: ' ·'; color: #4b5563; }
.footer-tags a:last-child::after { content: ''; }
.footer-tags a:hover, .footer-links a:hover { color: var(--gold); }
.footer-links { flex-direction: column; gap: 6px; }
.footer-links a { font-size: 0.83rem; }

/* CURRICULUM PAGE */
.learn-hero {
  background: var(--navy);
  color: #fff;
  padding: 40px 0;
  margin-bottom: 40px;
}
.learn-hero h1 {
  font-size: 1.8rem;
  font-weight: 800;
  margin-bottom: 12px;
}
.learn-hero p {
  font-size: 1rem;
  color: #9ca3af;
  max-width: 560px;
}
.learn-hero .signin-link {
  color: var(--gold);
  font-weight: 600;
  text-decoration: underline;
}
.curriculum-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 40px;
}
.curriculum-item {
  display: flex;
  align-items: center;
  gap: 16px;
  background: #fff;
  border-radius: 10px;
  padding: 18px 22px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  transition: transform 0.15s, box-shadow 0.15s;
  cursor: pointer;
  border: 2px solid transparent;
}
.curriculum-item:hover {
  transform: translateX(4px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.1);
  border-color: var(--gold);
}
.curriculum-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  flex-shrink: 0;
}
.curriculum-item h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
}
.curriculum-item p {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 2px;
}
.curriculum-arrow {
  margin-left: auto;
  color: var(--muted);
  font-size: 1.2rem;
}
.subsection-card {
  background: #fff;
  border-radius: 12px;
  padding: 28px;
  margin-bottom: 28px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.subsection-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 18px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}
.resource-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.resource-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.93rem;
  color: var(--text);
}
.resource-list li i { color: var(--gold); font-size: 1rem; flex-shrink: 0; }
.challenge-card {
  background: linear-gradient(135deg, #0a0a23 0%, #1a2a5e 100%);
  color: #fff;
  border-radius: 12px;
  padding: 32px;
  margin-bottom: 32px;
  text-align: center;
}
.challenge-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 20px;
}
.challenge-btns {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  background: var(--gold);
  color: var(--navy);
  padding: 12px 28px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.93rem;
  transition: background 0.15s;
  display: inline-block;
}
.btn-primary:hover { background: #f59e0b; color: var(--navy); }
.btn-outline {
  background: transparent;
  color: #fff;
  padding: 12px 28px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.93rem;
  border: 2px solid rgba(255,255,255,0.3);
  transition: border-color 0.15s, background 0.15s;
  display: inline-block;
}
.btn-outline:hover { border-color: #fff; background: rgba(255,255,255,0.08); color: #fff; }

/* DONATE PAGE */
.donate-hero {
  background: linear-gradient(135deg, var(--navy) 0%, #0d1d5e 100%);
  padding: 56px 0 48px;
  margin-bottom: 0;
}
.donate-hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
@media (max-width: 768px) {
  .donate-hero-inner { grid-template-columns: 1fr; gap: 32px; }
}
.donate-hero-text h1 {
  font-size: 2.2rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 18px;
  line-height: 1.25;
}
.donate-hero-text p {
  font-size: 1rem;
  color: #d1d5db;
  line-height: 1.7;
}
.donation-card {
  background: #fff;
  border-radius: 14px;
  padding: 32px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.2);
}
.amount-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
.amount-tab {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: #f9fafb;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
  text-align: center;
}
.amount-tab:hover { border-color: var(--gold); }
.amount-tab.active {
  border-color: var(--gold);
  background: var(--gold);
  color: var(--navy);
}
.donation-desc {
  font-size: 0.92rem;
  color: var(--muted);
  margin-bottom: 20px;
  min-height: 42px;
  line-height: 1.5;
}
.donation-desc strong { color: var(--navy); }
.donate-cta-btn {
  width: 100%;
  padding: 15px;
  background: var(--gold);
  color: var(--navy);
  border: none;
  border-radius: 8px;
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.donate-cta-btn:hover { background: #f59e0b; }
.donate-sub-label {
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
  margin-top: 10px;
}
.donate-sub-label a { color: var(--blue-link); text-decoration: underline; }
.donate-content { padding: 48px 0; }
.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-bottom: 40px;
}
@media (max-width: 768px) { .two-col { grid-template-columns: 1fr; } }
.info-card {
  background: #fff;
  border-radius: 12px;
  padding: 28px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.info-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.info-card h3 i { color: var(--gold); }
.benefits-list, .initiatives-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.benefits-list li, .initiatives-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.92rem;
  color: var(--text);
  line-height: 1.5;
}
.benefits-list li i { color: var(--gold); font-size: 1rem; flex-shrink: 0; margin-top: 2px; }
.initiatives-list li i { color: #3b82f6; font-size: 1rem; flex-shrink: 0; margin-top: 2px; }
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-bottom: 40px;
}
@media (max-width: 480px) { .stats-grid { grid-template-columns: 1fr; } }
.stat-card {
  background: var(--navy);
  color: #fff;
  border-radius: 12px;
  padding: 24px;
  text-align: center;
}
.stat-card .stat-num {
  font-size: 2rem;
  font-weight: 800;
  color: var(--gold);
  display: block;
}
.stat-card .stat-label {
  font-size: 0.83rem;
  color: #9ca3af;
  margin-top: 6px;
}

/* FAQ ACCORDION */
.faq-section { margin-bottom: 48px; }
.faq-section h2 {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 20px;
}
.accordion-item {
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 8px;
  background: #fff;
  overflow: hidden;
}
.accordion-btn {
  width: 100%;
  background: transparent;
  border: none;
  text-align: left;
  padding: 18px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: inherit;
  gap: 12px;
  transition: background 0.15s;
}
.accordion-btn:hover { background: #f9fafb; }
.accordion-icon {
  font-size: 1.2rem;
  color: var(--muted);
  transition: transform 0.25s;
  flex-shrink: 0;
}
.accordion-item.open .accordion-icon { transform: rotate(45deg); color: var(--navy); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  font-size: 0.9rem;
  color: var(--text);
  line-height: 1.7;
  padding: 0 20px;
}
.accordion-item.open .accordion-body {
  max-height: 300px;
  padding: 0 20px 18px;
}

/* TAG PAGES */
.tag-hero {
  background: var(--navy);
  padding: 36px 0 28px;
  margin-bottom: 32px;
}
.tag-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 6px;
}
.tag-hero .post-count {
  font-size: 0.9rem;
  color: #9ca3af;
}
.popular-tags-section { margin-bottom: 40px; }
.popular-tags-section h3 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.tags-scroll {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.pop-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 6px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  white-space: nowrap;
}
.pop-tag:hover { border-color: var(--navy); background: var(--navy); color: #fff; }
.pop-tag .tag-count {
  background: #f3f4f6;
  color: var(--muted);
  padding: 1px 7px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 500;
}
.pop-tag:hover .tag-count { background: rgba(255,255,255,0.15); color: #fff; }
